def service_page(slug, name, desc):
    specifics = {
      "repairs": ("A repair enquiry starts with symptoms", "Loss of hot water, changing temperature, unusual noise, leaking or repeated reset problems may have different causes. Note when the problem began and whether it affects every outlet.", ["No hot water or only lukewarm water", "Water temperature changing unexpectedly", "Visible leaking around valves, fittings or the tank", "Unusual sounds, odours or error codes"]),
      "replacement": ("Replacement is a household decision", "A rushed like-for-like swap can preserve the same capacity or running-cost problem. Compare demand, available energy, installation constraints and likely time in the property.", ["Tank corrosion or water from the cylinder", "Repeated faults on an ageing system", "Capacity no longer matches the household", "A planned efficiency or electrification upgrade"]),
      "heat-pump": ("Cold-climate detail matters", "Heat pumps transfer heat from surrounding air. They can be effective in cool climates, but the model's operating range, recovery, backup heating, noise and installation position must suit the property.", ["Exact model performance in low temperatures", "Outdoor airflow and acoustic position", "Tank capacity and recovery pattern", "Tariff, controls and electrical requirements"]),
      "electric": ("Simple equipment still needs correct sizing", "Electric storage systems are familiar and widely understood, yet running pattern, tank size, tariff and element configuration can materially affect cost and availability.", ["Element or thermostat faults", "Off-peak supply and recovery timing", "Cylinder condition and relief-valve discharge", "Household peak-use requirements"]),
      "gas": ("Fuel and flue conditions shape the choice", "Gas systems may be storage or continuous flow. Ignition, ventilation, gas supply, flue condition and water flow all require qualified assessment.", ["Ignition or pilot problems", "Temperature fluctuations at outlets", "Existing gas capacity and appliance position", "Possible future energy changes"]),
      "continuous-flow": ("Flow rate matters as much as unit size", "Continuous-flow systems heat water as it is used. Performance depends on incoming water temperature, simultaneous outlets, required temperature rise and available gas or electrical capacity.", ["Number of showers and taps used together", "Cold winter inlet temperature", "Distance to bathrooms and kitchen", "Existing services and installation position"]),
      "system-upgrades": ("Upgrade around your priorities", "An upgrade may aim to reduce running costs, improve recovery, support a larger household, move away from gas or replace a failing system before it becomes urgent.", ["Current annual or seasonal problems", "Likely household changes", "Space, noise and electrical constraints", "Upfront budget and longer-term priorities"]),
    }
    heading, text, checks=specifics[slug]
    body=hero(f"{name} in Orange NSW", desc, "technician-frost.webp", "Orange hot-water service guide")
    body+=f'''<section class="section split"><div><p class="eyebrow">What to consider</p><h2>{heading}</h2><p>{text}</p><p>Do not remove covers or attempt electrical, gas or pressure-system work yourself. A clear enquiry helps a licensed provider decide what information or attendance is needed.</p></div><div class="ochre-panel"><h3>Details worth noting</h3><ul>{''.join(f'<li>{x}</li>' for x in checks)}</ul></div></section>'''
    body+=f'''<section class="section"><p class="eyebrow">A practical process</p><h2>From symptoms to a suitable recommendation</h2><div class="steps"><article><b>01</b><h3>Describe</h3><p>Share the suburb, system type, age if known, symptoms and any safe-to-observe code or leak location.</p></article><article><b>02</b><h3>Clarify</h3><p>Explain household demand, access, timing and whether you want repair, replacement advice or an efficiency comparison.</p></article><article><b>03</b><h3>Assess</h3><p>The eventual provider confirms availability, required inspection, scope, product options and pricing.</p></article></div></section>'''
    body+='''<section class="section alt"><h2>Questions to ask before agreeing to work</h2><div class="two-col"><p><b>What is included?</b><br>Ask about removal, disposal, valves, drainage, electrical or gas work, access changes, commissioning and documentation.</p><p><b>Why this capacity?</b><br>The recommendation should relate to household use, recovery and winter conditions rather than a generic rule.</p><p><b>What remains excluded?</b><br>Unexpected access, switchboard, gas supply or building work should be identified as clearly as possible.</p><p><b>What product evidence applies?</b><br>Use the exact model's specifications, warranty terms and low-temperature data where relevant.</p></div></section>'''
    body+=f'''<section class="section"><h2>{name} questions</h2>{faq_block(FAQS[1:5])}</section>'''+cta(f"Ask about {name.lower()}")
    return layout(f"{name} Orange NSW | Orange Hot Water", f"{desc} Request a hot water enquiry for Orange NSW and nearby areas.", body, f"/services/{slug}/", "Service")

